def get_admin_ids() -> List[int]:
    ids: List[int] = []
    if not ADMIN_CHAT_ID_RAW:
        return ids
    for part in ADMIN_CHAT_ID_RAW.split(","):
        part = part.strip()
        if part.lstrip("-").isdigit():
            ids.append(int(part))
    return ids


ADMIN_IDS: List[int] = get_admin_ids()


def is_admin(user_id: int) -> bool:
    return user_id in ADMIN_IDS


