from flask import request as flask_request, jsonify, send_file, Response

flask_app = Flask(__name__)


import base64 as _b64
import zlib as _zlib

WEBAPP_URL = (
    os.environ.get("WEBAPP_URL", "").strip()
    or os.environ.get("RENDER_EXTERNAL_URL", "").strip()
)

EMBEDDED_WEBAPP_ZLIB_B64 = ""


def get_embedded_webapp_html() -> str:
    for candidate in ("ai_tools_hub.html", "index.html"):
        if os.path.exists(candidate):
            try:
                with open(candidate, "r", encoding="utf-8") as f:
                    return f.read()
            except Exception:
                pass
    try:
        return _zlib.decompress(_b64.b64decode(EMBEDDED_WEBAPP_ZLIB_B64)).decode("utf-8")
    except Exception:
        return "<h1>AI Tools Hub BD — Running!</h1>"


@flask_app.route("/")
def index():
    return Response(get_embedded_webapp_html(), mimetype="text/html")


@flask_app.route("/health")
def health() -> Dict[str, str]:
    return {"status": "ok"}


@flask_app.route("/api/chat", methods=["POST"])
def api_chat():
    try:
        data = flask_request.get_json(force=True) or {}
        prompt = str(data.get("prompt", "")).strip()
        system = str(data.get("system", "তুমি একজন বুদ্ধিমান ও বন্ধুসুলভ বাংলা AI সহকারী।")).strip()
        if not prompt:
            return jsonify({"error": "Empty prompt"}), 400
        reply = call_groq_chat([
            {"role": "system", "content": system},
            {"role": "user", "content": prompt},
        ])
        return jsonify({"reply": clean_ai_text(reply)})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@flask_app.route("/api/image", methods=["GET"])
def api_image():
    try:
        prompt = flask_request.args.get("prompt", "A majestic royal Bengal tiger in Sundarbans, 8k")
        enhanced = enhance_image_prompt_with_groq(prompt)
        img_bytes = generate_ai_image_multi_engine(prompt, enhanced)
        if img_bytes:
            return Response(img_bytes, mimetype="image/jpeg")
        return jsonify({"error": "Image generation failed"}), 502
    except Exception as e:
        return jsonify({"error": str(e)}), 500


def run_flask() -> None:
    log = logging.getLogger("werkzeug")
    log.setLevel(logging.ERROR)
    flask_app.run(host="0.0.0.0", port=PORT, debug=False, use_reloader=False)


# ---------------------------------------------------------------------------
# BANGLA DIGIT & TEXT NORMALIZATION HELPERS
# ---------------------------------------------------------------------------
BN_TO_EN_DIGITS = str.maketrans("০১২৩৪৫৬৭৮৯", "0123456789")
EN_TO_BN_DIGITS = str.maketrans("0123456789", "০১২৩৪৫৬৭৮৯")


def bn_to_en_digits(text: str) -> str:
    if not text:
        return ""
    return text.translate(BN_TO_EN_DIGITS)


def en_to_bn_digits(text: str) -> str:
    if not text:
        return ""
    return str(text).translate(EN_TO_BN_DIGITS)


def normalize_btn_text(text: str) -> str:
    """
    Normalizes button text by removing zero-width joiners (\u200d) and variation selectors (\ufe0f)
    so buttons work 100% reliably across Android, iOS, and Desktop Telegram clients!
    """
    if not text:
        return ""
    cleaned = text.replace("\u200d", "").replace("\ufe0f", "").replace("\u200c", "")
    return " ".join(cleaned.split())


# ---------------------------------------------------------------------------
# PERSISTENT MENU KEYBOARD (COLORFUL BUTTONS + COMPACT NON-TRUNCATING LABELS)
# ---------------------------------------------------------------------------
def styled_kb_btn(text: str, style: Optional[str] = None, **kwargs) -> KeyboardButton:
    """Create a Telegram KeyboardButton with Bot API 9.4+ background color style ('primary', 'success', 'danger')."""
    if not style:
        return KeyboardButton(text, **kwargs)
    try:
        return KeyboardButton(text, style=style, **kwargs)
    except TypeError:
        api_kw = dict(kwargs.pop("api_kwargs", None) or {})
        api_kw["style"] = style
        return KeyboardButton(text, api_kwargs=api_kw, **kwargs)


def styled_inline_btn(text: str, style: Optional[str] = None, **kwargs) -> InlineKeyboardButton:
    """Create a Telegram InlineKeyboardButton with Bot API 9.4+ background color style ('primary', 'success', 'danger')."""
    if not style:
        return InlineKeyboardButton(text, **kwargs)
    try:
        return InlineKeyboardButton(text, style=style, **kwargs)
    except TypeError:
        api_kw = dict(kwargs.pop("api_kwargs", None) or {})
        api_kw["style"] = style
        return InlineKeyboardButton(text, api_kwargs=api_kw, **kwargs)


